import pandas as pdfrom pathlib import PathDATA_DIR = Path("/Users/mihir/Desktop/internshipcrmls/csv")SOLD_FILE = DATA_DIR / "CRMLSSold_Residential_WithRates.csv"LISTING_FILE = DATA_DIR / "CRMLSListing_Residential_WithRates.csv"DATE_COLUMNS = [    "CloseDate",    "PurchaseContractDate",    "ListingContractDate",    "ContractStatusChangeDate",]NUMERIC_COLUMNS = [    "ClosePrice",    "ListPrice",    "OriginalListPrice",    "LivingArea",    "LotSizeAcres",    "LotSizeArea",    "LotSizeSquareFeet",    "BedroomsTotal",    "MainLevelBedrooms",    "BathroomsTotalInteger",    "DaysOnMarket",    "YearBuilt",    "Latitude",    "Longitude",    "ParkingTotal",    "GarageSpaces",    "AssociationFee",    "Stories",]# Redundant / unnecessary columnsREDUNDANT_COLUMNS = [    "HighSchoolDistrict",    "HighSchool",    "MiddleOrJuniorSchool",    "ElementarySchool",    "ListingId",    "StreetNumberNumeric",    "SubdivisionName",    "MlsStatus",    "BuyerAgentMlsId",    "BuyerAgencyCompensationType",    "OriginatingSystemSubName",    "OriginatingSystemName",]def convert_dates(df, name):    for column in DATE_COLUMNS:        if column in df.columns:            df[column] = pd.to_datetime(df[column], errors="coerce")    print(f"\n{name} date type confirmation:")    print(df[[c for c in DATE_COLUMNS if c in df.columns]].dtypes)    return dfdef remove_redundant_columns(df, name):    present = [c for c in REDUNDANT_COLUMNS if c in df.columns]    before = len(df.columns)    df = df.drop(columns=present)    after = len(df.columns)    print(f"\n{name} redundant columns removed: {present}")    print(f"{name}: {before} columns before -> {after} columns after")    return dfdef convert_numeric(df, name):    present = [c for c in NUMERIC_COLUMNS if c in df.columns]    for column in present:        df[column] = pd.to_numeric(df[column], errors="coerce")    print(f"\n{name} numeric type confirmation:")    print(df[present].dtypes)    return dfdef remove_invalid_values(df, name, is_sold):    before = len(df)    if "ClosePrice" in df.columns:        step_before = len(df)        if is_sold:            df = df[df["ClosePrice"] > 0]        else:            has_close_date = df["CloseDate"].notna()            invalid_closed_rows = has_close_date & ~(df["ClosePrice"] > 0)            df = df[~invalid_closed_rows]        print(f"{name}: dropped {step_before - len(df)} rows where ClosePrice <= 0")    if "LivingArea" in df.columns:        step_before = len(df)        df = df[df["LivingArea"] > 0]        print(f"{name}: dropped {step_before - len(df)} rows where LivingArea <= 0")    if "DaysOnMarket" in df.columns:        step_before = len(df)        df = df[df["DaysOnMarket"] >= 0]        print(f"{name}: dropped {step_before - len(df)} rows where DaysOnMarket < 0")    if "BedroomsTotal" in df.columns:        step_before = len(df)        df = df[df["BedroomsTotal"] >= 0]        print(f"{name}: dropped {step_before - len(df)} rows where BedroomsTotal < 0")    if "BathroomsTotalInteger" in df.columns:        step_before = len(df)        df = df[df["BathroomsTotalInteger"] >= 0]        print(f"{name}: dropped {step_before - len(df)} rows where BathroomsTotalInteger < 0")    after = len(df)    print(f"\n{name}: row count before invalid-value removal = {before}")    print(f"{name}: row count after invalid-value removal = {after}")    return dfdef flag_date_consistency(df, name):    df["listing_after_close_flag"] = df["ListingContractDate"] > df["PurchaseContractDate"]    df["purchase_after_close_flag"] = df["PurchaseContractDate"] > df["CloseDate"]    df["negative_timeline_flag"] = (        df["listing_after_close_flag"] | df["purchase_after_close_flag"]    )    print(f"\n{name} date consistency flag counts:")    print(f"  listing_after_close_flag: {df['listing_after_close_flag'].sum()}")    print(f"  purchase_after_close_flag: {df['purchase_after_close_flag'].sum()}")    print(f"  negative_timeline_flag: {df['negative_timeline_flag'].sum()}")    return dfdef flag_geographic_quality(df, name):    df["missing_latitude_flag"] = df["Latitude"].isna()    df["missing_longitude_flag"] = df["Longitude"].isna()    df["null_longitude_latitude_flag"] = (df["Latitude"] == 0) | (df["Longitude"] == 0)    df["longitude_error_flag"] = df["Longitude"] > 0    print(f"\n{name} geographic data quality summary:")    print(f"  missing_latitude_flag: {df['missing_latitude_flag'].sum()}")    print(f"  missing_longitude_flag: {df['missing_longitude_flag'].sum()}")    print(f"  null_longitude_latitude_flag: {df['null_longitude_latitude_flag'].sum()}")    print(f"  longitude_error_flag: {df['longitude_error_flag'].sum()}")    return dfdef clean_dataset(df, name, is_sold):    print(f"\n{'=' * 60}")    print(f"Weeks 4-5 cleaning: {name}")    print(f"{'=' * 60}")    row_count_start = len(df)    print(f"{name}: starting row count = {row_count_start}")    df = convert_dates(df, name)    df = remove_redundant_columns(df, name)    df = convert_numeric(df, name)    df = remove_invalid_values(df, name, is_sold)    df = flag_date_consistency(df, name)    df = flag_geographic_quality(df, name)    row_count_end = len(df)    print(f"\n{name}: final row count = {row_count_end}")    print(f"{name}: total rows removed = {row_count_start - row_count_end}")    return df# SOLDsold = pd.read_csv(SOLD_FILE, low_memory=False)clean_sold = clean_dataset(sold, "sold", is_sold=True)clean_sold.to_csv(DATA_DIR / "CRMLSSold_Clean.csv", index=False)# LISTING -- includes active/pending listings with no close yetlisting = pd.read_csv(LISTING_FILE, low_memory=False)clean_listing = clean_dataset(listing, "listing", is_sold=False)clean_listing.to_csv(DATA_DIR / "CRMLSListing_Clean.csv", index=False)print("\nExported CRMLSSold_Clean.csv and CRMLSListing_Clean.csv")